-- Bot Or Not — curated email dataset. GENERATED from data/emails.json by
-- scripts/build-email-seed.mjs. Do not edit by hand; edit the JSON and regenerate.
-- Idempotent + update-capable (matched on metadata->>'seedId'). 40 emails.

-- Retire the original placeholder emails (kept in table, just hidden from play).
UPDATE questions SET is_active = false
WHERE category_id = 'email' AND metadata->>'seedId' IN ('eml-001','eml-002','eml-003','eml-004','eml-005','eml-006');

-- Update existing curated rows in place (body, label, difficulty, explanation, metadata).
UPDATE questions q SET
  media_url = v.body,
  is_ai = v.is_ai,
  difficulty_rating = v.difficulty_rating,
  explanation_text = v.explanation,
  metadata = v.metadata,
  is_active = true
FROM (VALUES
  ('<div style="font-family:Arial,Helvetica,sans-serif;background:#ffffff;"><div style="background:#b91c1c;padding:14px 18px;"><span style="color:#ffffff;font-size:16px;font-weight:bold;letter-spacing:0.3px;">Account Security</span></div><div style="padding:18px;"><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">Dear Customer,</p><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">We detect unusual activity in your account. You must to confirm your password immediately or your account will be permanently suspend.</p><div style="margin:18px 0 8px;"><span style="display:inline-block;background:#b91c1c;color:#ffffff;padding:11px 22px;border-radius:6px;font-size:14px;font-weight:bold;">Verify account now</span></div><p style="margin:0;font-size:12px;color:#6b7280;word-break:break-all;">https://secure-verify-account.info/login</p></div><div style="padding:12px 18px;background:#f4f4f5;color:#71717a;font-size:11px;line-height:1.4;">This is an automated security notification. Do not reply.</div></div>', true, 'EASY', 'Stacked red flags: generic ''Dear Customer'', broken grammar (''must to confirm'', ''will be suspend''), a threat to create urgency, an unrelated ''.info'' domain, and a request to confirm your password — which no legitimate service ever asks for.', '{"kind":"email","subject":"Account Will Be Suspend !!","senderName":"Security Team","senderAddress":"support@secure-verify-account.info","bodyFormat":"html","seedId":"eml-101"}'::jsonb),
  ('<div style="font-family:Arial,Helvetica,sans-serif;background:#ffffff;"><div style="background:#ffcc00;padding:14px 18px;"><span style="color:#1a1a1a;font-size:16px;font-weight:bold;letter-spacing:0.3px;">DHL Express</span></div><div style="padding:18px;"><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">Hello Dear,</p><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">Your package is hold at our facility because of unpaid customs fee of $2.99. Please to pay now otherwise parcel will be return.</p><div style="margin:18px 0 8px;"><span style="display:inline-block;background:#ffcc00;color:#1a1a1a;padding:11px 22px;border-radius:6px;font-size:14px;font-weight:bold;">Pay customs fee</span></div><p style="margin:0;font-size:12px;color:#6b7280;word-break:break-all;">https://dhl-parcel-clearance.top/pay</p></div><div style="padding:12px 18px;background:#f4f4f5;color:#71717a;font-size:11px;line-height:1.4;">DHL automated delivery notification.</div></div>', true, 'EASY', '''Hello Dear'', awkward grammar (''is wait'', ''Please to pay''), a tiny fee designed to bait a card entry, and a suspicious ''.top'' domain unrelated to dhl.com.', '{"kind":"email","subject":"Your parcel is wait for you","senderName":"DHL Notification","senderAddress":"auto@dhl-parcel-clearance.top","bodyFormat":"html","seedId":"eml-102"}'::jsonb),
  ('<div style="padding:16px;font-family:Arial,Helvetica,sans-serif;color:#1a1a1a;font-size:14px;line-height:1.6;">Hey team, quick notes from this morning''s standup are in the shared doc. Nothing blocking this week. Thanks!</div>', false, 'EASY', 'Internal sender on company.com, natural tone, and no links or requests to act on — an ordinary colleague message.', '{"kind":"email","subject":"Standup notes — Tue","senderName":"Marcus Lee","senderAddress":"marcus.lee@company.com","bodyFormat":"html","seedId":"eml-103"}'::jsonb),
  ('<div style="font-family:Arial,Helvetica,sans-serif;background:#ffffff;"><div style="background:#0a66c2;padding:14px 18px;"><span style="color:#ffffff;font-size:16px;font-weight:bold;letter-spacing:0.3px;">LinkedIn</span></div><div style="padding:18px;"><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">You have 3 new connection requests waiting for your response.</p><div style="margin:18px 0 8px;"><span style="display:inline-block;background:#0a66c2;color:#ffffff;padding:11px 22px;border-radius:6px;font-size:14px;font-weight:bold;">View invitations</span></div><p style="margin:0;font-size:12px;color:#6b7280;word-break:break-all;">https://www.linkedin.com/invitations</p></div><div style="padding:12px 18px;background:#f4f4f5;color:#71717a;font-size:11px;line-height:1.4;">You are receiving connection notifications from LinkedIn.</div></div>', false, 'EASY', 'Genuine linkedin.com sender and link, informational, and it does not ask for credentials.', '{"kind":"email","subject":"You have 3 new invitations","senderName":"LinkedIn","senderAddress":"notifications-noreply@linkedin.com","bodyFormat":"html","seedId":"eml-104"}'::jsonb),
  ('<div style="font-family:Arial,Helvetica,sans-serif;background:#ffffff;"><div style="background:#1e1e1e;padding:14px 18px;"><span style="color:#ffffff;font-size:16px;font-weight:bold;letter-spacing:0.3px;">Figma</span></div><div style="padding:18px;"><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">New this month: variables, improved auto-layout, and more.</p><div style="margin:18px 0 8px;"><span style="display:inline-block;background:#1e1e1e;color:#ffffff;padding:11px 22px;border-radius:6px;font-size:14px;font-weight:bold;">Read the changelog</span></div><p style="margin:0;font-size:12px;color:#6b7280;word-break:break-all;">https://www.figma.com/whats-new</p></div><div style="padding:12px 18px;background:#f4f4f5;color:#71717a;font-size:11px;line-height:1.4;">You are subscribed to Figma product updates.</div></div>', false, 'EASY', 'Legitimate figma.com sender and link; a routine product newsletter with nothing sensitive to act on.', '{"kind":"email","subject":"What''s new in Figma this month","senderName":"Figma","senderAddress":"updates@figma.com","bodyFormat":"html","seedId":"eml-105"}'::jsonb),
  ('<div style="font-family:Arial,Helvetica,sans-serif;background:#ffffff;"><div style="background:#003087;padding:14px 18px;"><span style="color:#ffffff;font-size:16px;font-weight:bold;letter-spacing:0.3px;">PayPal</span></div><div style="padding:18px;"><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">You sent a payment of $649.99 to Tech Store Ltd.</p><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">If you did not authorize this payment, cancel it within 24 hours.</p><div style="margin:18px 0 8px;"><span style="display:inline-block;background:#003087;color:#ffffff;padding:11px 22px;border-radius:6px;font-size:14px;font-weight:bold;">Cancel this payment</span></div><p style="margin:0;font-size:12px;color:#6b7280;word-break:break-all;">https://paypal-notifications.com/cancel</p></div><div style="padding:12px 18px;background:#f4f4f5;color:#71717a;font-size:11px;line-height:1.4;">Automated transaction notice.</div></div>', true, 'MEDIUM', 'A fake ''you paid'' alarm to make you click in a panic. PayPal emails come from paypal.com; ''paypal-notifications.com'' is a look-alike domain.', '{"kind":"email","subject":"You sent a payment of $649.99","senderName":"PayPal Service","senderAddress":"service@paypal-notifications.com","bodyFormat":"html","seedId":"eml-106"}'::jsonb),
  ('<div style="font-family:Arial,Helvetica,sans-serif;background:#ffffff;"><div style="background:#0067b8;padding:14px 18px;"><span style="color:#ffffff;font-size:16px;font-weight:bold;letter-spacing:0.3px;">Microsoft 365</span></div><div style="padding:18px;"><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">We has detected a sign-in from a new device.</p><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">If this wasnt you, please verify you identity to secure the account.</p><div style="margin:18px 0 8px;"><span style="display:inline-block;background:#0067b8;color:#ffffff;padding:11px 22px;border-radius:6px;font-size:14px;font-weight:bold;">Verify identity</span></div><p style="margin:0;font-size:12px;color:#6b7280;word-break:break-all;">https://microsoft365-alerts.com/verify</p></div><div style="padding:12px 18px;background:#f4f4f5;color:#71717a;font-size:11px;line-height:1.4;">Microsoft automated account notification.</div></div>', true, 'MEDIUM', 'Grammar slips (''We has detected'', ''wasnt'', ''you identity'') plus a look-alike domain; Microsoft uses microsoft.com, not ''microsoft365-alerts.com''.', '{"kind":"email","subject":"Unusual sign in activity","senderName":"Microsoft 365","senderAddress":"no-reply@microsoft365-alerts.com","bodyFormat":"html","seedId":"eml-107"}'::jsonb),
  ('<div style="font-family:Arial,Helvetica,sans-serif;background:#ffffff;"><div style="background:#635bff;padding:14px 18px;"><span style="color:#ffffff;font-size:16px;font-weight:bold;letter-spacing:0.3px;">Stripe</span></div><div style="padding:18px;"><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">Your invoice for $420.00 is available to view or download.</p><div style="margin:18px 0 8px;"><span style="display:inline-block;background:#635bff;color:#ffffff;padding:11px 22px;border-radius:6px;font-size:14px;font-weight:bold;">View invoice</span></div><p style="margin:0;font-size:12px;color:#6b7280;word-break:break-all;">https://dashboard.stripe.com/invoices</p></div><div style="padding:12px 18px;background:#f4f4f5;color:#71717a;font-size:11px;line-height:1.4;">This invoice was sent by Stripe on behalf of your account.</div></div>', false, 'MEDIUM', 'It''s an invoice, but everything is consistent: a stripe.com sender and a dashboard.stripe.com link. The topic alone doesn''t make it a scam.', '{"kind":"email","subject":"Invoice 4F2A-9C for $420.00","senderName":"Stripe","senderAddress":"invoice+statements@stripe.com","bodyFormat":"html","seedId":"eml-108"}'::jsonb),
  ('<div style="font-family:Arial,Helvetica,sans-serif;background:#ffffff;"><div style="background:#117aca;padding:14px 18px;"><span style="color:#ffffff;font-size:16px;font-weight:bold;letter-spacing:0.3px;">Chase</span></div><div style="padding:18px;"><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">A payment of $1,204.00 to your credit card posted today.</p><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">You can review recent activity any time by signing in at chase.com.</p></div><div style="padding:12px 18px;background:#f4f4f5;color:#71717a;font-size:11px;line-height:1.4;">You set up this alert in your Chase profile.</div></div>', false, 'MEDIUM', 'An alarming amount, but the sender is chase.com and it only reports activity — no link to a login form and no request for details.', '{"kind":"email","subject":"A payment of $1,204.00 posted","senderName":"Chase","senderAddress":"no.reply.alerts@chase.com","bodyFormat":"html","seedId":"eml-109"}'::jsonb),
  ('<div style="font-family:Arial,Helvetica,sans-serif;background:#ffffff;"><div style="background:#0067b8;padding:14px 18px;"><span style="color:#ffffff;font-size:16px;font-weight:bold;letter-spacing:0.3px;">Microsoft</span></div><div style="padding:18px;"><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">We noticed a new sign-in to your Microsoft account on a Windows PC.</p><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">If this wasn''t you, secure your account now.</p><div style="margin:18px 0 8px;"><span style="display:inline-block;background:#0067b8;color:#ffffff;padding:11px 22px;border-radius:6px;font-size:14px;font-weight:bold;">Secure account</span></div><p style="margin:0;font-size:12px;color:#6b7280;word-break:break-all;">https://rnicrosoft.com/security</p></div><div style="padding:12px 18px;background:#f4f4f5;color:#71717a;font-size:11px;line-height:1.4;">Microsoft account security notification.</div></div>', true, 'HARD', 'The copy is clean, so the domain is the tell: ''rnicrosoft.com'' uses the letters r and n to imitate an m. The real domain is microsoft.com.', '{"kind":"email","subject":"New sign-in to your account","senderName":"Microsoft account team","senderAddress":"account-security-noreply@rnicrosoft.com","bodyFormat":"html","seedId":"eml-110"}'::jsonb),
  ('<div style="font-family:Arial,Helvetica,sans-serif;background:#ffffff;"><div style="background:#000000;padding:14px 18px;"><span style="color:#ffffff;font-size:16px;font-weight:bold;letter-spacing:0.3px;">Apple</span></div><div style="padding:18px;"><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">Your Apple ID was used to sign in to iCloud on a new device.</p><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">If this wasn''t you, review your account activity right away.</p><div style="margin:18px 0 8px;"><span style="display:inline-block;background:#000000;color:#ffffff;padding:11px 22px;border-radius:6px;font-size:14px;font-weight:bold;">Review activity</span></div><p style="margin:0;font-size:12px;color:#6b7280;word-break:break-all;">https://appleid-verify.com/signin</p></div><div style="padding:12px 18px;background:#f4f4f5;color:#71717a;font-size:11px;line-height:1.4;">This message was sent regarding your Apple ID.</div></div>', true, 'HARD', 'Even though the sender looks right, the action link goes to ''appleid-verify.com'', not apple.com — a link mismatch. Check the destination, not just the sender.', '{"kind":"email","subject":"Your Apple ID was used to sign in","senderName":"Apple","senderAddress":"no-reply@apple.com","bodyFormat":"html","seedId":"eml-111"}'::jsonb),
  ('<div style="font-family:Arial,Helvetica,sans-serif;background:#ffffff;"><div style="background:#0067b8;padding:14px 18px;"><span style="color:#ffffff;font-size:16px;font-weight:bold;letter-spacing:0.3px;">Microsoft</span></div><div style="padding:18px;"><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">Security info was recently added to your Microsoft account.</p><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">If this was you, no action is needed. You can manage security info at account.microsoft.com.</p></div><div style="padding:12px 18px;background:#f4f4f5;color:#71717a;font-size:11px;line-height:1.4;">Microsoft account security notification.</div></div>', false, 'HARD', 'The long subdomain ''accountprotection.microsoft.com'' looks intimidating but is a genuine Microsoft domain; the email informs and points to account.microsoft.com.', '{"kind":"email","subject":"Security info was added","senderName":"Microsoft account team","senderAddress":"account-security-noreply@accountprotection.microsoft.com","bodyFormat":"html","seedId":"eml-112"}'::jsonb),
  ('<div style="padding:16px;font-family:Arial,Helvetica,sans-serif;color:#1a1a1a;font-size:14px;line-height:1.6;">Hi — following up on our call. Can you process the $8,400 payment to the new vendor today? I''ll send the remittance details separately. Thanks, Sarah</div>', true, 'EXPERT', 'Reads like a normal colleague, but the domain is ''cornpany.com'' (c-o-r-n mimicking the m in company.com) — an external sender impersonating an internal one (business email compromise).', '{"kind":"email","subject":"Re: Vendor payment","senderName":"Sarah Chen","senderAddress":"sarah.chen@cornpany.com","bodyFormat":"html","seedId":"eml-113"}'::jsonb),
  ('<div style="font-family:Arial,Helvetica,sans-serif;background:#ffffff;"><div style="background:#f2c94c;padding:14px 18px;"><span style="color:#1a1a1a;font-size:16px;font-weight:bold;letter-spacing:0.3px;">DocuSign</span></div><div style="padding:18px;"><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">John Alvarez sent you ''Mutual NDA'' to review and sign.</p><div style="margin:18px 0 8px;"><span style="display:inline-block;background:#f2c94c;color:#1a1a1a;padding:11px 22px;border-radius:6px;font-size:14px;font-weight:bold;">Review document</span></div><p style="margin:0;font-size:12px;color:#6b7280;word-break:break-all;">https://na4.docusign.net/review</p></div><div style="padding:12px 18px;background:#f4f4f5;color:#71717a;font-size:11px;line-height:1.4;">This notification was sent by DocuSign, Inc.</div></div>', false, 'EXPERT', 'docusign.net is DocuSign''s genuine sending domain (not docusign.com), which can look off but is legitimate; there''s no credential request.', '{"kind":"email","subject":"John Alvarez sent you a document to review","senderName":"DocuSign","senderAddress":"dse_na4@docusign.net","bodyFormat":"html","seedId":"eml-114"}'::jsonb),
  ('<div style="font-family:Arial,Helvetica,sans-serif;background:#ffffff;"><div style="background:#0875e1;padding:14px 18px;"><span style="color:#ffffff;font-size:16px;font-weight:bold;letter-spacing:0.3px;">Workday</span></div><div style="padding:18px;"><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">Payroll is processing. Please confirm your direct deposit details before the cutoff.</p><div style="margin:18px 0 8px;"><span style="display:inline-block;background:#0875e1;color:#ffffff;padding:11px 22px;border-radius:6px;font-size:14px;font-weight:bold;">Confirm direct deposit</span></div><p style="margin:0;font-size:12px;color:#6b7280;word-break:break-all;">https://workday-hrportal.com/dd</p></div><div style="padding:12px 18px;background:#f4f4f5;color:#71717a;font-size:11px;line-height:1.4;">Automated payroll notification.</div></div>', true, 'MEDIUM', 'Workday runs on myworkday.com; ''workday-hrportal.com'' is a look-alike built to capture your bank details.', '{"kind":"email","subject":"Action needed: confirm direct deposit","senderName":"Workday","senderAddress":"no-reply@workday-hrportal.com","bodyFormat":"html","seedId":"eml-115"}'::jsonb),
  ('<div style="padding:16px;font-family:Arial,Helvetica,sans-serif;color:#1a1a1a;font-size:14px;line-height:1.6;">Reminder: please submit your timesheet by Friday 5pm in Workday. The link is on the intranet.</div>', false, 'MEDIUM', 'Internal payroll from company.com; a routine reminder with no external link or data request.', '{"kind":"email","subject":"Timesheet reminder","senderName":"HR — Payroll","senderAddress":"payroll@company.com","bodyFormat":"html","seedId":"eml-116"}'::jsonb),
  ('<div style="font-family:Arial,Helvetica,sans-serif;background:#ffffff;"><div style="background:#232f3e;padding:14px 18px;"><span style="color:#ffffff;font-size:16px;font-weight:bold;letter-spacing:0.3px;">amazon</span></div><div style="padding:18px;"><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">Your refund of $63.20 is ready.</p><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">To receive it, confirm the card on file.</p><div style="margin:18px 0 8px;"><span style="display:inline-block;background:#232f3e;color:#ffffff;padding:11px 22px;border-radius:6px;font-size:14px;font-weight:bold;">Confirm card</span></div><p style="margin:0;font-size:12px;color:#6b7280;word-break:break-all;">https://arnazon.com/refund</p></div><div style="padding:12px 18px;background:#f4f4f5;color:#71717a;font-size:11px;line-height:1.4;">Automated message from Amazon returns.</div></div>', true, 'HARD', '''arnazon.com'' uses r-n to imitate the m in amazon.com — and Amazon never asks you to re-confirm a card to receive a refund.', '{"kind":"email","subject":"Your refund is ready","senderName":"Amazon.com","senderAddress":"returns@arnazon.com","bodyFormat":"html","seedId":"eml-117"}'::jsonb),
  ('<div style="font-family:Arial,Helvetica,sans-serif;background:#ffffff;"><div style="background:#232f3e;padding:14px 18px;"><span style="color:#ffffff;font-size:16px;font-weight:bold;letter-spacing:0.3px;">amazon</span></div><div style="padding:18px;"><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">We''ve issued your refund of $24.30 to your Visa ending in 4412. It may take 3-5 business days to appear.</p></div><div style="padding:12px 18px;background:#f4f4f5;color:#71717a;font-size:11px;line-height:1.4;">Automated message from Amazon. Please do not reply.</div></div>', false, 'MEDIUM', 'An amazon.com sender that states an outcome, requests nothing, and doesn''t link to any form.', '{"kind":"email","subject":"Refund issued","senderName":"Amazon.com","senderAddress":"auto-confirm@amazon.com","bodyFormat":"html","seedId":"eml-118"}'::jsonb),
  ('<div style="font-family:Arial,Helvetica,sans-serif;background:#ffffff;"><div style="background:#1b3a5b;padding:14px 18px;"><span style="color:#ffffff;font-size:16px;font-weight:bold;letter-spacing:0.3px;">Online Banking</span></div><div style="padding:18px;"><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">Dear user, to protect you account please reply with the 6 digit code we just send to your phone.</p><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">Failure to do so will lock you account.</p></div><div style="padding:12px 18px;background:#f4f4f5;color:#71717a;font-size:11px;line-height:1.4;">Automated security message.</div></div>', true, 'EASY', 'No real bank asks you to share a one-time code. Combined with ''Dear user'', grammar errors, and an unrelated domain, it''s clearly phishing.', '{"kind":"email","subject":"Verify your one time code","senderName":"Bank Support","senderAddress":"helpdesk@online-bank-secure.com","bodyFormat":"html","seedId":"eml-119"}'::jsonb),
  ('<div style="font-family:Arial,Helvetica,sans-serif;background:#ffffff;"><div style="background:#4a154b;padding:14px 18px;"><span style="color:#ffffff;font-size:16px;font-weight:bold;letter-spacing:0.3px;">Slack</span></div><div style="padding:18px;"><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">You have 5 unread messages in #project-orion.</p><div style="margin:18px 0 8px;"><span style="display:inline-block;background:#4a154b;color:#ffffff;padding:11px 22px;border-radius:6px;font-size:14px;font-weight:bold;">Open Slack</span></div><p style="margin:0;font-size:12px;color:#6b7280;word-break:break-all;">https://app.slack.com</p></div><div style="padding:12px 18px;background:#f4f4f5;color:#71717a;font-size:11px;line-height:1.4;">You are receiving activity notifications from Slack.</div></div>', false, 'EASY', 'Genuine slack.com sender and app.slack.com link; a routine notification.', '{"kind":"email","subject":"You have unread messages","senderName":"Slack","senderAddress":"feedback@slack.com","bodyFormat":"html","seedId":"eml-120"}'::jsonb),
  ('<div style="font-family:Arial,Helvetica,sans-serif;background:#ffffff;"><div style="background:#4285f4;padding:14px 18px;"><span style="color:#ffffff;font-size:16px;font-weight:bold;letter-spacing:0.3px;">Google Docs</span></div><div style="padding:18px;"><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">A document ''Contract_Final.pdf'' was shared with you.</p><div style="margin:18px 0 8px;"><span style="display:inline-block;background:#4285f4;color:#ffffff;padding:11px 22px;border-radius:6px;font-size:14px;font-weight:bold;">Open in Docs</span></div><p style="margin:0;font-size:12px;color:#6b7280;word-break:break-all;">https://google-docs-share.com/d/xY7</p></div><div style="padding:12px 18px;background:#f4f4f5;color:#71717a;font-size:11px;line-height:1.4;">Google Docs sharing notification.</div></div>', true, 'MEDIUM', 'Real Google sharing comes from google.com / docs.google.com; ''google-docs-share.com'' is an unrelated look-alike.', '{"kind":"email","subject":"Contract_Final has been shared with you","senderName":"Google Docs","senderAddress":"no-reply@google-docs-share.com","bodyFormat":"html","seedId":"eml-121"}'::jsonb),
  ('<div style="padding:16px;font-family:Arial,Helvetica,sans-serif;color:#1a1a1a;font-size:14px;line-height:1.6;">Sharing the Q3 deck ahead of tomorrow: https://company.sharepoint.com/:p:/r/sites/marketing/Q3.pptx</div>', false, 'HARD', 'An internal company.com sender and a company.sharepoint.com link — both consistent with the organization, so it''s legitimate despite the long URL.', '{"kind":"email","subject":"Q3 deck","senderName":"Priya Nair","senderAddress":"priya.nair@company.com","bodyFormat":"html","seedId":"eml-122"}'::jsonb),
  ('<div style="font-family:Arial,Helvetica,sans-serif;background:#ffffff;"><div style="background:#e50914;padding:14px 18px;"><span style="color:#ffffff;font-size:16px;font-weight:bold;letter-spacing:0.3px;">NETFLIX</span></div><div style="padding:18px;"><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">We''re having trouble with your current payment method.</p><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">To avoid interruption to your membership, update your payment details.</p><div style="margin:18px 0 8px;"><span style="display:inline-block;background:#e50914;color:#ffffff;padding:11px 22px;border-radius:6px;font-size:14px;font-weight:bold;">Update payment</span></div><p style="margin:0;font-size:12px;color:#6b7280;word-break:break-all;">https://netfl1x.com/account</p></div><div style="padding:12px 18px;background:#f4f4f5;color:#71717a;font-size:11px;line-height:1.4;">This is an automated message from Netflix.</div></div>', true, 'EXPERT', '''netfl1x.com'' replaces the i with a 1; the genuine domain is netflix.com. The message itself is well written, so the domain is the only tell.', '{"kind":"email","subject":"We couldn''t process your payment","senderName":"Netflix","senderAddress":"info@netfl1x.com","bodyFormat":"html","seedId":"eml-123"}'::jsonb),
  ('<div style="font-family:Arial,Helvetica,sans-serif;background:#ffffff;"><div style="background:#e50914;padding:14px 18px;"><span style="color:#ffffff;font-size:16px;font-weight:bold;letter-spacing:0.3px;">NETFLIX</span></div><div style="padding:18px;"><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">Your payment of $15.49 was received. You can manage your plan any time in Account settings.</p></div><div style="padding:12px 18px;background:#f4f4f5;color:#71717a;font-size:11px;line-height:1.4;">This is an automated message from Netflix.</div></div>', false, 'MEDIUM', 'account.netflix.com is a genuine Netflix domain; a simple receipt with nothing to click urgently.', '{"kind":"email","subject":"Your receipt from Netflix","senderName":"Netflix","senderAddress":"info@account.netflix.com","bodyFormat":"html","seedId":"eml-124"}'::jsonb),
  ('<div style="font-family:Arial,Helvetica,sans-serif;background:#ffffff;"><div style="background:#2f3b52;padding:14px 18px;"><span style="color:#ffffff;font-size:16px;font-weight:bold;letter-spacing:0.3px;">IT Helpdesk</span></div><div style="padding:18px;"><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">Your mailbox has exceeded its storage limit.</p><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">Re-validate your account now to keep receiving mail.</p><div style="margin:18px 0 8px;"><span style="display:inline-block;background:#2f3b52;color:#ffffff;padding:11px 22px;border-radius:6px;font-size:14px;font-weight:bold;">Re-validate account</span></div><p style="margin:0;font-size:12px;color:#6b7280;word-break:break-all;">https://mailbox-revalidate.com</p></div><div style="padding:12px 18px;background:#f4f4f5;color:#71717a;font-size:11px;line-height:1.4;">Automated mailbox notification.</div></div>', true, 'MEDIUM', 'A corporate IT desk would not email from a personal gmail.com address, and the re-validation link points to an unrelated domain.', '{"kind":"email","subject":"Mailbox storage exceeded","senderName":"IT Helpdesk","senderAddress":"corp.it.helpdesk@gmail.com","bodyFormat":"html","seedId":"eml-125"}'::jsonb),
  ('<div style="padding:16px;font-family:Arial,Helvetica,sans-serif;color:#1a1a1a;font-size:14px;line-height:1.6;">Heads up: VPN maintenance Saturday 10pm-2am. No action needed; access may be briefly unavailable.</div>', false, 'EASY', 'Internal company.com sender; informational, with nothing to click.', '{"kind":"email","subject":"Planned maintenance this weekend","senderName":"IT Service Desk","senderAddress":"servicedesk@company.com","bodyFormat":"html","seedId":"eml-126"}'::jsonb),
  ('<div style="font-family:Arial,Helvetica,sans-serif;background:#ffffff;"><div style="background:#4d148c;padding:14px 18px;"><span style="color:#ffffff;font-size:16px;font-weight:bold;letter-spacing:0.3px;">FedEx</span></div><div style="padding:18px;"><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">We attempted to deliver your package but no one was available.</p><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">Reschedule your delivery to receive it.</p><div style="margin:18px 0 8px;"><span style="display:inline-block;background:#4d148c;color:#ffffff;padding:11px 22px;border-radius:6px;font-size:14px;font-weight:bold;">Reschedule delivery</span></div><p style="margin:0;font-size:12px;color:#6b7280;word-break:break-all;">https://fedex-deliverysupport.com/reschedule</p></div><div style="padding:12px 18px;background:#f4f4f5;color:#71717a;font-size:11px;line-height:1.4;">FedEx automated delivery notification.</div></div>', true, 'HARD', 'The wording is clean, so the domain is the tell: FedEx uses fedex.com, and the added ''-deliverysupport'' marks a look-alike.', '{"kind":"email","subject":"Delivery attempt failed","senderName":"FedEx","senderAddress":"tracking@fedex-deliverysupport.com","bodyFormat":"html","seedId":"eml-127"}'::jsonb),
  ('<div style="font-family:Arial,Helvetica,sans-serif;background:#ffffff;"><div style="background:#4d148c;padding:14px 18px;"><span style="color:#ffffff;font-size:16px;font-weight:bold;letter-spacing:0.3px;">FedEx</span></div><div style="padding:18px;"><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">Your package is out for delivery and should arrive today.</p><div style="margin:18px 0 8px;"><span style="display:inline-block;background:#4d148c;color:#ffffff;padding:11px 22px;border-radius:6px;font-size:14px;font-weight:bold;">Track package</span></div><p style="margin:0;font-size:12px;color:#6b7280;word-break:break-all;">https://www.fedex.com/track</p></div><div style="padding:12px 18px;background:#f4f4f5;color:#71717a;font-size:11px;line-height:1.4;">FedEx automated delivery notification.</div></div>', false, 'EASY', 'Sender and link are both fedex.com; a routine delivery update.', '{"kind":"email","subject":"Your package is out for delivery","senderName":"FedEx","senderAddress":"trackingupdates@fedex.com","bodyFormat":"html","seedId":"eml-128"}'::jsonb),
  ('<div style="font-family:Arial,Helvetica,sans-serif;background:#ffffff;"><div style="background:#f2c94c;padding:14px 18px;"><span style="color:#1a1a1a;font-size:16px;font-weight:bold;letter-spacing:0.3px;">DocuSign</span></div><div style="padding:18px;"><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">You have a document waiting for your signature.</p><div style="margin:18px 0 8px;"><span style="display:inline-block;background:#f2c94c;color:#1a1a1a;padding:11px 22px;border-radius:6px;font-size:14px;font-weight:bold;">Review and sign</span></div><p style="margin:0;font-size:12px;color:#6b7280;word-break:break-all;">https://docusign-secure-sign.com/sign</p></div><div style="padding:12px 18px;background:#f4f4f5;color:#71717a;font-size:11px;line-height:1.4;">This notification was sent by DocuSign.</div></div>', true, 'MEDIUM', 'DocuSign sends from docusign.net; ''docusign-secure-sign.com'' is an unrelated look-alike domain.', '{"kind":"email","subject":"You have a document waiting","senderName":"DocuSign","senderAddress":"dse@docusign-secure-sign.com","bodyFormat":"html","seedId":"eml-129"}'::jsonb),
  ('<div style="font-family:Arial,Helvetica,sans-serif;background:#ffffff;"><div style="background:#4285f4;padding:14px 18px;"><span style="color:#ffffff;font-size:16px;font-weight:bold;letter-spacing:0.3px;">Google</span></div><div style="padding:18px;"><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">Your Google Account was just signed in to on a new Windows device.</p><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">If this was you, you don''t need to do anything. You can review activity in your account.</p></div><div style="padding:12px 18px;background:#f4f4f5;color:#71717a;font-size:11px;line-height:1.4;">You received this email to let you know about important changes to your Google Account.</div></div>', false, 'MEDIUM', 'accounts.google.com is genuine; the alert is informational and does not ask for your password.', '{"kind":"email","subject":"Security alert: new sign-in on Windows","senderName":"Google","senderAddress":"no-reply@accounts.google.com","bodyFormat":"html","seedId":"eml-130"}'::jsonb),
  ('<div style="font-family:Arial,Helvetica,sans-serif;background:#ffffff;"><div style="background:#1a73e8;padding:14px 18px;"><span style="color:#ffffff;font-size:16px;font-weight:bold;letter-spacing:0.3px;">Google Calendar</span></div><div style="padding:18px;"><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">You have been invited to ''Q2 Budget Review'' on Thursday 2:00pm.</p><div style="margin:18px 0 8px;"><span style="display:inline-block;background:#1a73e8;color:#ffffff;padding:11px 22px;border-radius:6px;font-size:14px;font-weight:bold;">Join meeting</span></div><p style="margin:0;font-size:12px;color:#6b7280;word-break:break-all;">https://g00gle-invites.com/j/BR2Q</p></div><div style="padding:12px 18px;background:#f4f4f5;color:#71717a;font-size:11px;line-height:1.4;">You are receiving this because you have a Google Calendar.</div></div>', true, 'EXPERT', 'The invite looks completely routine, but ''g00gle'' uses zeros for the o''s; genuine invites come from google.com.', '{"kind":"email","subject":"Invitation: Q2 Budget Review","senderName":"Google Calendar","senderAddress":"calendar-invite@g00gle-invites.com","bodyFormat":"html","seedId":"eml-131"}'::jsonb),
  ('<div style="font-family:Arial,Helvetica,sans-serif;background:#ffffff;"><div style="background:#1a73e8;padding:14px 18px;"><span style="color:#ffffff;font-size:16px;font-weight:bold;letter-spacing:0.3px;">Google Calendar</span></div><div style="padding:18px;"><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">You''ve been invited to ''Design sync'' on Monday 11:00am.</p><div style="margin:18px 0 8px;"><span style="display:inline-block;background:#1a73e8;color:#ffffff;padding:11px 22px;border-radius:6px;font-size:14px;font-weight:bold;">Join with Google Meet</span></div><p style="margin:0;font-size:12px;color:#6b7280;word-break:break-all;">https://meet.google.com/abc-defg</p></div><div style="padding:12px 18px;background:#f4f4f5;color:#71717a;font-size:11px;line-height:1.4;">You are receiving this because you have a Google Calendar.</div></div>', false, 'EASY', 'Genuine google.com sender and a meet.google.com link; an ordinary calendar invite.', '{"kind":"email","subject":"Invitation: Design sync","senderName":"Google Calendar","senderAddress":"calendar-notification@google.com","bodyFormat":"html","seedId":"eml-132"}'::jsonb),
  ('<div style="font-family:Arial,Helvetica,sans-serif;background:#ffffff;"><div style="background:#2ca01c;padding:14px 18px;"><span style="color:#ffffff;font-size:16px;font-weight:bold;letter-spacing:0.3px;">QuickBooks</span></div><div style="padding:18px;"><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">Invoice INV-88213 for $1,290.00 is overdue.</p><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">Please pay promptly to avoid a late fee.</p><div style="margin:18px 0 8px;"><span style="display:inline-block;background:#2ca01c;color:#ffffff;padding:11px 22px;border-radius:6px;font-size:14px;font-weight:bold;">Pay invoice</span></div><p style="margin:0;font-size:12px;color:#6b7280;word-break:break-all;">https://intuit-invoices.net/pay</p></div><div style="padding:12px 18px;background:#f4f4f5;color:#71717a;font-size:11px;line-height:1.4;">Automated billing notification.</div></div>', true, 'HARD', 'The invoice framing is normal — the domain is the tell. Intuit/QuickBooks invoices come from intuit.com; ''intuit-invoices.net'' is an unrelated look-alike.', '{"kind":"email","subject":"Invoice INV-88213 is overdue","senderName":"QuickBooks","senderAddress":"billing@intuit-invoices.net","bodyFormat":"html","seedId":"eml-133"}'::jsonb),
  ('<div style="font-family:Arial,Helvetica,sans-serif;background:#ffffff;"><div style="background:#000000;padding:14px 18px;"><span style="color:#ffffff;font-size:16px;font-weight:bold;letter-spacing:0.3px;">Apple</span></div><div style="padding:18px;"><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">Your Apple ID was used to buy ''Logic Pro'' for $199.99.</p><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">If you didn''t make this purchase, you can review your purchase history in the App Store.</p></div><div style="padding:12px 18px;background:#f4f4f5;color:#71717a;font-size:11px;line-height:1.4;">This is a receipt for your recent purchase.</div></div>', false, 'HARD', 'email.apple.com is genuine; the charge is alarming but the email only points you to the App Store, not to a login form.', '{"kind":"email","subject":"Your receipt from Apple","senderName":"Apple","senderAddress":"no_reply@email.apple.com","bodyFormat":"html","seedId":"eml-134"}'::jsonb),
  ('<div style="font-family:Arial,Helvetica,sans-serif;background:#ffffff;"><div style="background:#7a1f6b;padding:14px 18px;"><span style="color:#ffffff;font-size:16px;font-weight:bold;letter-spacing:0.3px;">Benefits Portal</span></div><div style="padding:18px;"><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">All employee must to re-enroll in benefits before end of day today or coverage will be lost.</p><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">Login here to confirm your enrollment.</p><div style="margin:18px 0 8px;"><span style="display:inline-block;background:#7a1f6b;color:#ffffff;padding:11px 22px;border-radius:6px;font-size:14px;font-weight:bold;">Confirm enrollment</span></div><p style="margin:0;font-size:12px;color:#6b7280;word-break:break-all;">https://company-benefits-portal.com</p></div><div style="padding:12px 18px;background:#f4f4f5;color:#71717a;font-size:11px;line-height:1.4;">Automated HR notification.</div></div>', true, 'MEDIUM', 'Grammar errors (''Update you benefits'', ''All employee must to re-enroll''), false urgency, and an external domain posing as your employer''s benefits portal.', '{"kind":"email","subject":"Update you benefits before deadline","senderName":"HR Department","senderAddress":"hr@company-benefits-portal.com","bodyFormat":"html","seedId":"eml-135"}'::jsonb),
  ('<div style="padding:16px;font-family:Arial,Helvetica,sans-serif;color:#1a1a1a;font-size:14px;line-height:1.6;">Open enrollment runs Nov 4-15. No action needed today; details and the enrollment link will be posted on the intranet.</div>', false, 'MEDIUM', 'Internal company.com sender, no urgency, and no external link — a normal HR announcement.', '{"kind":"email","subject":"Open enrollment starts Monday","senderName":"People Team","senderAddress":"people@company.com","bodyFormat":"html","seedId":"eml-136"}'::jsonb),
  ('<div style="font-family:Arial,Helvetica,sans-serif;background:#ffffff;"><div style="background:#1b3a5b;padding:14px 18px;"><span style="color:#ffffff;font-size:16px;font-weight:bold;letter-spacing:0.3px;">SecureBank</span></div><div style="padding:18px;"><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">We has place a hold on you account.</p><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">To remove the hold you must confirm your card number and PIN.</p><div style="margin:18px 0 8px;"><span style="display:inline-block;background:#1b3a5b;color:#ffffff;padding:11px 22px;border-radius:6px;font-size:14px;font-weight:bold;">Unlock account</span></div><p style="margin:0;font-size:12px;color:#6b7280;word-break:break-all;">https://secure-bank-online.com/unlock</p></div><div style="padding:12px 18px;background:#f4f4f5;color:#71717a;font-size:11px;line-height:1.4;">Automated account notification.</div></div>', true, 'EASY', 'Banks never ask for your PIN by email. Combined with ''You account'', ''We has place'', and a generic domain, it''s clearly a scam.', '{"kind":"email","subject":"You account is on hold","senderName":"SecureBank Alert","senderAddress":"alert@secure-bank-online.com","bodyFormat":"html","seedId":"eml-137"}'::jsonb),
  ('<div style="font-family:Arial,Helvetica,sans-serif;background:#ffffff;"><div style="background:#232f3e;padding:14px 18px;"><span style="color:#ffffff;font-size:16px;font-weight:bold;letter-spacing:0.3px;">amazon</span></div><div style="padding:18px;"><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">Your order of ''USB-C cable'' has shipped and arrives Thursday.</p><div style="margin:18px 0 8px;"><span style="display:inline-block;background:#232f3e;color:#ffffff;padding:11px 22px;border-radius:6px;font-size:14px;font-weight:bold;">Track your order</span></div><p style="margin:0;font-size:12px;color:#6b7280;word-break:break-all;">https://www.amazon.com/orders</p></div><div style="padding:12px 18px;background:#f4f4f5;color:#71717a;font-size:11px;line-height:1.4;">Automated message from Amazon. Please do not reply.</div></div>', false, 'EASY', 'amazon.com sender and link; a routine shipping confirmation with no action needed.', '{"kind":"email","subject":"Your order has shipped","senderName":"Amazon.com","senderAddress":"ship-confirm@amazon.com","bodyFormat":"html","seedId":"eml-138"}'::jsonb),
  ('<div style="font-family:Arial,Helvetica,sans-serif;background:#ffffff;"><div style="background:#0061ff;padding:14px 18px;"><span style="color:#ffffff;font-size:16px;font-weight:bold;letter-spacing:0.3px;">Dropbox</span></div><div style="padding:18px;"><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">Someone shared ''Payroll_2024.xlsx'' with you on Dropbox.</p><div style="margin:18px 0 8px;"><span style="display:inline-block;background:#0061ff;color:#ffffff;padding:11px 22px;border-radius:6px;font-size:14px;font-weight:bold;">View file</span></div><p style="margin:0;font-size:12px;color:#6b7280;word-break:break-all;">https://dropbox-fileshare.com/view</p></div><div style="padding:12px 18px;background:#f4f4f5;color:#71717a;font-size:11px;line-height:1.4;">Dropbox sharing notification.</div></div>', true, 'HARD', 'The wording is clean, so check the domain: Dropbox shares come from dropbox.com, and ''dropbox-fileshare.com'' is a look-alike.', '{"kind":"email","subject":"A file was shared with you","senderName":"Dropbox","senderAddress":"no-reply@dropbox-fileshare.com","bodyFormat":"html","seedId":"eml-139"}'::jsonb),
  ('<div style="font-family:Arial,Helvetica,sans-serif;background:#ffffff;"><div style="background:#0061ff;padding:14px 18px;"><span style="color:#ffffff;font-size:16px;font-weight:bold;letter-spacing:0.3px;">Dropbox</span></div><div style="padding:18px;"><p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#1a1a1a;">The file you requested is ready to download from your Dropbox account.</p><div style="margin:18px 0 8px;"><span style="display:inline-block;background:#0061ff;color:#ffffff;padding:11px 22px;border-radius:6px;font-size:14px;font-weight:bold;">Go to Dropbox</span></div><p style="margin:0;font-size:12px;color:#6b7280;word-break:break-all;">https://www.dropbox.com/home</p></div><div style="padding:12px 18px;background:#f4f4f5;color:#71717a;font-size:11px;line-height:1.4;">Dropbox notification.</div></div>', false, 'MEDIUM', 'Genuine dropbox.com sender and link; informational.', '{"kind":"email","subject":"Your file is ready","senderName":"Dropbox","senderAddress":"no-reply@dropbox.com","bodyFormat":"html","seedId":"eml-140"}'::jsonb)
